CREATE TABLE billing_accounts (
	id VARCHAR(32) NOT NULL, 
	org_id VARCHAR(32) NOT NULL, 
	"plan" VARCHAR(50) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	provider VARCHAR(20), 
	provider_customer_id VARCHAR(200), 
	provider_subscription_id VARCHAR(200), 
	last_event_id VARCHAR(200), 
	last_event_at DATETIME, 
	needs_reconciliation BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (provider, provider_subscription_id), 
	UNIQUE (org_id), 
	FOREIGN KEY(org_id) REFERENCES orgs (id)
);
CREATE TABLE billing_events (
	id VARCHAR(32) NOT NULL, 
	provider VARCHAR(20) NOT NULL, 
	event_id VARCHAR(200) NOT NULL, 
	org_id VARCHAR(32), 
	event_time DATETIME, 
	applied BOOLEAN NOT NULL, 
	note VARCHAR(100) NOT NULL, 
	received_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (provider, event_id)
);
CREATE TABLE connections (
	id VARCHAR(32) NOT NULL, 
	org_id VARCHAR(32) NOT NULL, 
	owner_principal_id VARCHAR(32) NOT NULL, 
	instance_id VARCHAR(32) NOT NULL, 
	credential_digest VARCHAR(64) NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	revoked_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(org_id) REFERENCES orgs (id), 
	FOREIGN KEY(owner_principal_id) REFERENCES principals (id), 
	FOREIGN KEY(instance_id) REFERENCES logical_instances (id)
);
CREATE TABLE grants (
	id VARCHAR(32) NOT NULL, 
	org_id VARCHAR(32) NOT NULL, 
	principal_id VARCHAR(32) NOT NULL, 
	scope_id VARCHAR(32) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (principal_id, scope_id), 
	FOREIGN KEY(org_id) REFERENCES orgs (id), 
	FOREIGN KEY(principal_id) REFERENCES principals (id), 
	FOREIGN KEY(scope_id) REFERENCES scopes (id)
);
